#define main retained_test_client_main
#include "/workspace/scratch/906cef4a9bba/bouncer-baseline/vipirc-0.7.28/tests/test_client.c"
#undef main

int main(void)
{
    char directory[] = "/tmp/irc-composer-inherit-XXXXXX";
    char path[CONFIG_PATH_MAX], error[512];
    Config primary, secondary, fresh, loaded;
    Client *client = calloc(1, sizeof *client);
    Client *restart = calloc(1, sizeof *restart);
    size_t index;
    assert(client && restart && mkdtemp(directory));
    assert(snprintf(path, sizeof path, "%s/config.ini", directory) > 0);
    config_defaults(&primary);
    strcpy(primary.server, "primary.invalid");
    strcpy(primary.nick, "Tester");
    primary.composer_fullscreen = 1;
    assert(config_save(&primary, path, error, sizeof error) > 0);
    assert(client_init(client, &primary, path, "tester", 0, 1, error, sizeof error) > 0);
    client_new_config(client, &fresh);
    printf("new profile composer_fullscreen=%d expected=1\n", fresh.composer_fullscreen);
    secondary = fresh;
    strcpy(secondary.server, "secondary.invalid");
    secondary.composer_fullscreen = 0;
    assert(client_add(client, &secondary, &index, error, sizeof error) > 0);
    printf("added profile composer_fullscreen=%d expected=1\n", client->slots[index].seed.composer_fullscreen);
    assert(client_save(client, index, &secondary, error, sizeof error) > 0);
    config_defaults(&loaded);
    assert(config_load(&loaded, path, error, sizeof error) > 0);
    assert(client_init(restart, &loaded, path, "tester", 0, 1, error, sizeof error) > 0);
    printf("reloaded profile composer_fullscreen=%d expected=1\n", restart->slots[index].seed.composer_fullscreen);
    int failed = !fresh.composer_fullscreen || !client->slots[index].seed.composer_fullscreen ||
                 !restart->slots[index].seed.composer_fullscreen;
    client_free(client); client_free(restart); free(client); free(restart);
    remove_tree(directory);
    return failed;
}

