/* Synthetic incoming control echoes only. In-memory transport/config doubles;
 * real App parser/renderer/log writer, private temporary output, no network. */
#define main established_app_test_main
#include "/workspace/scratch/906cef4a9bba/bouncer-work/vipirc-0.7.29/tests/test_app.c"
#undef main

int main(void)
{
    for (int type = CONFIG_BOUNCER_ZNC; type <= CONFIG_BOUNCER_SOJU; ++type) {
        App *a = fresh(0);
        register_plain(a);
        a->cfg.bouncer_type = type;
        a->cfg.tls = a->authenticated = a->cap_batch = 1;
        char directory[] = "/tmp/irc-control-replay-XXXXXXXX";
        assert(mkdtemp(directory));
        snprintf(a->config_path, sizeof a->config_path, "%s/config.ini", directory);
        char logfile[CONFIG_PATH_MAX + 5], frame[256], data[4096];
        snprintf(logfile, sizeof logfile, "%s.log", a->config_path);
        a->cfg.persistent_logging = 1;
        const char *target = type == CONFIG_BOUNCER_ZNC ? "*sasl" : "BouncerServ";
        snprintf(frame, sizeof frame, ":tester!u@h PRIVMSG %s :create -pass LIVE_CANARY\r\n", target);
        feed(a, frame);
        feed(a, ":server BATCH +old chathistory\r\n");
        snprintf(frame, sizeof frame, "@batch=old :tester!u@h PRIVMSG %s :create -pass HISTORY_CANARY\r\n", target);
        feed(a, frame);
        feed(a, ":server BATCH -old\r\n");
        size_t used = 0;
        FILE *file = fopen(logfile, "rb");
        if (file) { used = fread(data, 1, sizeof data - 1, file); fclose(file); }
        data[used] = 0;
        printf("type=%s retained_live=%d retained_history=%d persisted_live=%d persisted_history=%d\n",
               type == CONFIG_BOUNCER_ZNC ? "ZNC" : "soju",
               !!logs_contain(a, "LIVE_CANARY"), !!logs_contain(a, "HISTORY_CANARY"),
               !!strstr(data, "LIVE_CANARY"), !!strstr(data, "HISTORY_CANARY"));
        destroy(a);
        if (file) assert(!unlink(logfile));
        assert(!rmdir(directory));
    }
    return 0;
}
